import{_ as t,o as n,c as s,a0 as r}from"./chunks/framework.DVUHX04-.js";const u=JSON.parse('{"title":"Docs screenshots render by capture pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0017-docs-screenshots-render-by-capture-pipeline.md","filePath":"adr/0017-docs-screenshots-render-by-capture-pipeline.md","lastUpdated":1789775493000}'),a={name:"adr/0017-docs-screenshots-render-by-capture-pipeline.md"};function i(o,e,d,c,l,h){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="docs-screenshots-render-by-capture-pipeline" tabindex="-1">Docs screenshots render by capture pipeline <a class="header-anchor" href="#docs-screenshots-render-by-capture-pipeline" aria-label="Permalink to &quot;Docs screenshots render by capture pipeline&quot;">​</a></h1><p>The docs show each extension&#39;s UI as screenshots, but pi is a terminal app: live data, logins, and transient notifications mean a hand-taken image rots without anyone noticing. So no Screenshot is ever taken by hand. A Capture script renders every Screenshot from the extension&#39;s real UI code with committed Fixture data, captures the real terminal for the surfaces where the terminal is the product (CLI output, pi&#39;s persistent notifications), pins the terminal look (grid size, theme, font), and a CI job re-renders and fails when a committed Screenshot no longer matches.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Hand-taken terminal screenshots.</strong> Simplest, but the quota numbers are live, some UI is transient, and nothing detects staleness.</li><li><strong>Off-screen rendering only.</strong> Covers the TUI views, but not the real terminal surfaces (CLI output, pi&#39;s own chrome).</li><li><strong>Terminal screencast tooling (VHS family).</strong> A real terminal emulator, but a fixed built-in font, so the shot cannot match the user&#39;s terminal.</li><li><strong>Browser rendering (Playwright + xterm.js).</strong> Most WYSIWYG, but a browser download in the repo to rasterize static text.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The terminal font TTF and golden PNG files are checked into the repo, and the render pins grid size, theme, and font, so local and CI renders are byte-identical.</li><li>The font pin is exact at the rasterizer boundary: the SVG font-family is the family name inside the committed TTFs&#39; name tables, resvg loads only the committed file paths with system fonts disabled, and the theme color mode is pinned by environment (COLORTERM) before pi&#39;s theme loader runs. A golden test proves the committed TTFs are what rasterizes: the same screen rendered without the font files must differ.</li><li>The real-pi captures run with stub <code>fd</code> and <code>rg</code> binaries on PATH so pi&#39;s &quot;not found&quot; startup warnings - which depend on what the rendering machine has installed - never reach the screen.</li><li>Adding a Screenshot is a Capture definition (extension, view, capture method, fixture); the pipeline does not change.</li><li>A UI change that alters a view&#39;s appearance is a capture re-run, and CI fails until the image is updated.</li></ul>',6)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
